/* ========================================
   LearnForge — Global Styles
   ======================================== */

/* ---- CSS Variables ---- */
:root {
  --primary: #000000;
  --primary-foreground: #ffffff;
  --accent: #E6FF32;
  --accent-dark: #d4eb2a;
  --burgundy: #7F2A23;
  --background: #ffffff;
  --foreground: #0a0a0a;
  --muted: #f5f5f5;
  --muted-foreground: #737373;
  --border: #e5e5e5;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --font-sans: 'Plus Jakarta Sans', Inter, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
}

/* ---- Reset & Base ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--foreground);
  background: var(--background);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ---- Container ---- */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

@media (min-width: 768px) {
  .container {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: 3rem;
    padding-right: 3rem;
  }
}

/* ---- Typography ---- */
.text-display {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.text-h1 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.text-h2 {
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.text-h3 {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 700;
  line-height: 1.3;
}

.text-body {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--muted-foreground);
}

.text-body-lg {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--muted-foreground);
}

.text-small {
  font-size: 0.875rem;
  line-height: 1.5;
}

.text-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius);
  transition: all 200ms ease-out;
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--primary-foreground);
}

.btn-primary:hover {
  background: #1a1a1a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--primary);
}

.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--foreground);
  border: 1.5px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--foreground);
  background: var(--muted);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}

.btn-ghost:hover {
  background: var(--muted);
}

/* ---- Cards ---- */
.card {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all 200ms ease-out;
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-filled {
  background: var(--muted);
  border: none;
  border-radius: var(--radius-lg);
  padding: 1.5rem;
}

/* ---- Section Spacing ---- */
.section {
  padding: 4rem 0;
}

@media (min-width: 768px) {
  .section {
    padding: 5rem 0;
  }
}

@media (min-width: 1024px) {
  .section {
    padding: 6rem 0;
  }
}

.section-title {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 3rem;
}

.section-title h2 {
  margin-bottom: 0.75rem;
}

/* ---- Header / Nav ---- */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo-icon {
  width: 2rem;
  height: 2rem;
  background: var(--accent);
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 0.25rem;
}

.nav-links a {
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius);
  transition: background 150ms;
}

.nav-links a:hover {
  background: var(--muted);
}

.nav-links a.active {
  background: var(--muted);
  font-weight: 600;
}

.nav-cta {
  display: none;
}

.nav-mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius);
}

.nav-mobile-toggle:hover {
  background: var(--muted);
}

.nav-mobile-menu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--background);
  border-bottom: 1px solid var(--border);
  padding: 1rem;
  box-shadow: var(--shadow-lg);
}

.nav-mobile-menu.open {
  display: block;
}

.nav-mobile-menu a {
  display: block;
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  border-radius: var(--radius);
}

.nav-mobile-menu a:hover {
  background: var(--muted);
}

.nav-mobile-menu .btn {
  margin-top: 0.75rem;
  width: 100%;
}

@media (min-width: 1024px) {
  .nav-links {
    display: flex;
  }
  .nav-cta {
    display: flex;
  }
  .nav-mobile-toggle {
    display: none;
  }
}

/* ---- Hero ---- */
.hero {
  position: relative;
  overflow: hidden;
  padding: 4rem 0 5rem;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.hero-bg::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 60%;
  height: 80%;
  background: radial-gradient(ellipse at center, rgba(230, 255, 50, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  gap: 3rem;
  align-items: center;
}

@media (min-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
  }
}

.hero-content {
  max-width: 600px;
}

.hero-title {
  margin-bottom: 1.25rem;
}

.hero-subtitle {
  margin-bottom: 2rem;
  font-size: 1.125rem;
  color: var(--muted-foreground);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.hero-visual {
  position: relative;
}

.hero-visual-frame {
  background: var(--muted);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  aspect-ratio: 16/10;
  position: relative;
}

.hero-visual-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ---- Tabs ---- */
.tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--muted);
  padding: 0.25rem;
  border-radius: var(--radius);
  width: fit-content;
  margin-bottom: 1.5rem;
}

.tab-btn {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: calc(var(--radius) - 0.125rem);
  transition: all 150ms;
  color: var(--muted-foreground);
}

.tab-btn:hover {
  color: var(--foreground);
}

.tab-btn.active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: var(--shadow-sm);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
  animation: fadeIn 300ms ease-out;
}

/* ---- Stats Bar ---- */
.stats-bar {
  background: var(--primary);
  color: var(--primary-foreground);
  padding: 2.5rem 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  text-align: center;
}

.stat-value {
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--accent);
}

.stat-label {
  font-size: 0.875rem;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 0.25rem;
}

/* ---- Feature Grid ---- */
.feature-grid {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 640px) {
  .feature-grid.cols-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .feature-grid.cols-3 {
    grid-template-columns: repeat(3, 1fr);
  }
  .feature-grid.cols-4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

.feature-card {
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--background);
  transition: all 200ms ease-out;
}

.feature-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.feature-icon {
  width: 2.5rem;
  height: 2.5rem;
  background: var(--accent);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
  color: var(--primary);
}

.feature-icon-burgundy {
  background: var(--burgundy);
  color: #fff;
}

.feature-title {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.feature-desc {
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  line-height: 1.6;
}

/* ---- Why Choose Tabs ---- */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
  justify-content: center;
}

.why-tab-btn {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius);
  border: 1.5px solid var(--border);
  transition: all 150ms;
  color: var(--muted-foreground);
}

.why-tab-btn:hover {
  border-color: var(--foreground);
  color: var(--foreground);
}

.why-tab-btn.active {
  background: var(--primary);
  color: var(--primary-foreground);
  border-color: var(--primary);
}

.why-panel {
  display: none;
}

.why-panel.active {
  display: grid;
  animation: fadeIn 300ms ease-out;
}

.why-panel-grid {
  display: grid;
  gap: 1rem;
}

@media (min-width: 768px) {
  .why-panel-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.why-item {
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
  padding: 1.25rem;
  background: var(--muted);
  border-radius: var(--radius);
}

.why-item-icon {
  width: 1.75rem;
  height: 1.75rem;
  flex-shrink: 0;
  color: var(--accent-dark);
  margin-top: 0.125rem;
}

.why-item-text {
  font-size: 0.9375rem;
  line-height: 1.5;
}

/* ---- Testimonials ---- */
.testimonials {
  overflow: hidden;
}

.testimonial-carousel {
  position: relative;
}

.testimonial-track {
  display: flex;
  gap: 1.5rem;
  transition: transform 400ms ease-out;
}

.testimonial-card {
  flex: 0 0 100%;
  max-width: 100%;
  padding: 2rem;
  background: var(--muted);
  border-radius: var(--radius-lg);
}

@media (min-width: 768px) {
  .testimonial-card {
    flex: 0 0 calc(50% - 0.75rem);
    max-width: calc(50% - 0.75rem);
  }
}

@media (min-width: 1024px) {
  .testimonial-card {
    flex: 0 0 calc(33.333% - 1rem);
    max-width: calc(33.333% - 1rem);
  }
}

.testimonial-quote {
  font-size: 1rem;
  line-height: 1.7;
  margin-bottom: 1.5rem;
  font-style: italic;
}

.testimonial-author {
  font-weight: 700;
  font-size: 0.9375rem;
}

.testimonial-company {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

.testimonial-tag {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  background: var(--accent);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: 9999px;
  margin-bottom: 0.75rem;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  border: 1.5px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 150ms;
}

.carousel-btn:hover {
  background: var(--primary);
  color: var(--primary-foreground);
  border-color: var(--primary);
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--border);
  transition: all 150ms;
}

.carousel-dot.active {
  background: var(--primary);
  width: 1.25rem;
  border-radius: 9999px;
}

/* ---- FAQ ---- */
.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  transition: color 150ms;
}

.faq-question:hover {
  color: var(--burgundy);
}

.faq-icon {
  width: 1.25rem;
  height: 1.25rem;
  flex-shrink: 0;
  transition: transform 200ms ease-out;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out, padding 300ms ease-out;
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding-bottom: 1.25rem;
}

.faq-answer p {
  color: var(--muted-foreground);
  line-height: 1.7;
}

/* ---- Pricing ---- */
.pricing-grid {
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .pricing-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.pricing-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1.5px solid var(--border);
  background: var(--background);
  transition: all 200ms ease-out;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.pricing-card.featured {
  border-color: var(--primary);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -0.75rem;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.875rem;
  border-radius: 9999px;
}

.pricing-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  margin-bottom: 1.25rem;
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 0.25rem;
}

.pricing-period {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  margin-bottom: 1.5rem;
}

.pricing-features {
  margin-bottom: 1.5rem;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.375rem 0;
  font-size: 0.9375rem;
}

.pricing-features li svg {
  width: 1.125rem;
  height: 1.125rem;
  color: var(--accent-dark);
  flex-shrink: 0;
}

/* ---- Integrations ---- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

@media (min-width: 640px) {
  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (min-width: 768px) {
  .integrations-grid {
    grid-template-columns: repeat(5, 1fr);
  }
}

@media (min-width: 1024px) {
  .integrations-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1.25rem 0.75rem;
  background: var(--muted);
  border-radius: var(--radius);
  transition: all 150ms;
}

.integration-item:hover {
  background: var(--border);
}

.integration-icon {
  width: 2.5rem;
  height: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--background);
  border-radius: var(--radius);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary);
}

.integration-name {
  font-size: 0.8125rem;
  font-weight: 600;
  text-align: center;
}

/* ---- CTA Banner ---- */
.cta-banner {
  background: var(--primary);
  color: var(--primary-foreground);
  padding: 4rem 0;
  text-align: center;
}

.cta-banner .section-title h2 {
  color: #fff;
}

.cta-banner .section-title p {
  color: rgba(255, 255, 255, 0.75);
}

/* ---- Footer ---- */
.footer {
  background: var(--muted);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  gap: 2.5rem;
  margin-bottom: 3rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: 2fr repeat(4, 1fr);
  }
}

.footer-brand {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.footer-brand-desc {
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  max-width: 280px;
}

.footer-col-title {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.footer-links a {
  display: block;
  padding: 0.375rem 0;
  font-size: 0.9375rem;
  color: var(--muted-foreground);
  transition: color 150ms;
}

.footer-links a:hover {
  color: var(--foreground);
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
  }
}

.footer-copy {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

/* ---- Steps ---- */
.steps {
  display: grid;
  gap: 2rem;
}

@media (min-width: 768px) {
  .steps {
    grid-template-columns: repeat(3, 1fr);
  }
}

.step {
  position: relative;
  text-align: center;
}

.step-number {
  width: 3rem;
